Add-Type -AssemblyName UIAutomationClient; Add-Type -AssemblyName UIAutomationTypes; $hwnd = (Get-Process -Name notepad | Select-Object -First 1).MainWindowHandle; if (-not $hwnd) { Write-Output 'Notepad not running'; exit 0 }; $el = [System.Windows.Automation.AutomationElement]::FromHandle($hwnd); function Dump($e, $depth) { if ($depth -gt 4) { return }; $indent = '  ' * $depth; $nm = $e.Current.Name; Write-Output ($indent + 'Name=' + $nm); $cond = [System.Windows.Automation.Automation]::ControlViewCondition; $kids = $e.FindAll([System.Windows.Automation.TreeScope]::Children, $cond); foreach ($k in $kids) { Dump $k ($depth+1) } }; Dump $el 0
